with prev_events as (select *, lag(txn_time) over (partition by account_id order by txn_time, id) as prev_txn_time from transactions), gaps as (select *, case when prev_txn_time is null or txn_time > prev_txn_time + interval 7 days then 1 else 0 end as session_start_flag from prev_events), sessions_transactions as (select *, sum(session_start_flag) over (partition by account_id order by txn_time, id rows between unbounded preceding and current row) as session_no from gaps) select s.id, s.account_id, s.txn_type, s.amount, s.txn_time, s.is_flagged, s.session_no, (select max(x.amount) from transactions x where x.account_id = s.account_id) as max_transaction_amount from sessions_transactions s order by account_id desc nulls last, txn_type
